import heapq


def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    if not jobs or k <= 0:
        return 0

    coords = sorted({t for s, e, _ in jobs for t in (s, e)})
    idx = {t: i for i, t in enumerate(coords)}
    m = len(coords)

    # Adjacency list: [to, cap, cost, rev]
    graph: list[list[list[int]]] = [[] for _ in range(m)]

    def add_edge(u: int, v: int, cap: int, cost: int) -> None:
        graph[u].append([v, cap, cost, len(graph[v])])
        graph[v].append([u, 0, -cost, len(graph[u]) - 1])

    for i in range(m - 1):
        add_edge(i, i + 1, k, 0)

    for s, e, pay in jobs:
        add_edge(idx[s], idx[e], 1, -pay)

    # Initial potentials via DAG shortest path from 0
    INF = 10**18
    pot = [INF] * m
    pot[0] = 0
    for u in range(m):
        if pot[u] == INF:
            continue
        for v, cap, cost, _ in graph[u]:
            if cap > 0 and pot[u] + cost < pot[v]:
                pot[v] = pot[u] + cost

    total_pay = 0
    for _ in range(k):
        dist = [INF] * m
        parent_v = [-1] * m
        parent_e = [-1] * m
        dist[0] = 0
        pq = [(0, 0)]

        while pq:
            d, u = heapq.heappop(pq)
            if d > dist[u]:
                continue
            for ei, (v, cap, cost, _) in enumerate(graph[u]):
                if cap > 0:
                    nd = d + cost + pot[u] - pot[v]
                    if nd < dist[v]:
                        dist[v] = nd
                        parent_v[v] = u
                        parent_e[v] = ei
                        heapq.heappush(pq, (nd, v))

        if dist[m - 1] == INF:
            break

        for i in range(m):
            if dist[i] < INF:
                pot[i] += dist[i]

        if pot[m - 1] >= 0:
            break

        total_pay -= pot[m - 1]

        v = m - 1
        while v != 0:
            u = parent_v[v]
            ei = parent_e[v]
            edge = graph[u][ei]
            edge[1] -= 1
            graph[v][edge[3]][1] += 1
            v = u

    return total_pay
